import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/EnhancedSuffixArray.html","title":"EnhancedSuffixArray","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":3.34,"words":1001},"filePathRelative":"EnhancedSuffixArray.md"}`),a={name:`EnhancedSuffixArray.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="enhancedsuffixarray" tabindex="-1"><a class="header-anchor" href="#enhancedsuffixarray"><span>EnhancedSuffixArray</span></a></h1><p><a href="./SuffixArray.html">SuffixArray</a>, <a href="./原論文から解き明かす生成AI.html">原論文から解き明かす生成AI</a>, <a href="./アルゴリズム.html">アルゴリズム</a>, <a href="./論文.html">論文</a></p><ul><li><a href="https://www.mi.fu-berlin.de/wiki/pub/ABI/RnaSeqP4/enhanced-suffix-array.pdf" target="_blank" rel="noopener noreferrer">Enhanced Suffix Array.pdf</a></li><li><a href="https://www.sciencedirect.com/science/article/pii/S1570866703000650" target="_blank" rel="noopener noreferrer">Replacing suffix trees with enhanced suffix arrays - ScienceDirect</a> 元論文</li></ul><p>Suffix Arrayとlcptableをベースに追加的な線形時間で作れる補助データ構造を使う事で、Suffix Treeと同じオーダーの時間で検索等を実現出来る。 この補助データ構造とSuffix ArrayをあわせたものをEnhanced Suffix Arrayという。</p><p>Suffix Treeの効率的な保持方法と解釈する事が出来る。トラバースも配列を順番に見ていくだけで高速。</p><p>追加のテーブルとしてはlcptableが基本。＞<a href="https://en.wikipedia.org/wiki/LCP_array" target="_blank" rel="noopener noreferrer">LCP array - Wikipedia</a></p><p>以下では<a href="https://www.sciencedirect.com/science/article/pii/S1570866703000650" target="_blank" rel="noopener noreferrer">Replacing suffix trees with enhanced suffix arrays - ScienceDirect</a>を読んでいったメモを中心にまとめる。</p><h2 id="suffix-tree" tabindex="-1"><a class="header-anchor" href="#suffix-tree"><span>Suffix Tree</span></a></h2><p><img src="/RandomThoughts/assets/0000-DwFxTdBc.png" alt="imgs/EnhancedSuffixArray/0000.png"></p><h2 id="suffix-array" tabindex="-1"><a class="header-anchor" href="#suffix-array"><span>Suffix Array</span></a></h2><p><img src="/RandomThoughts/assets/0001-CyM_lrqL.png" alt="imgs/EnhancedSuffixArray/0001.png"></p><p>lcpテーブルはSA-ISを変更して同時に作る事が出来るらしい。</p><p><a href="https://arxiv.org/abs/1101.3448" target="_blank" rel="noopener noreferrer">arxiv:1101.3448 Inducing the LCP-Array</a></p><h2 id="repeat分析" tabindex="-1"><a class="header-anchor" href="#repeat分析"><span>Repeat分析</span></a></h2><p><img src="/RandomThoughts/assets/0002-BR-sgv5Y.png" alt="imgs/EnhancedSuffixArray/0002.png"></p><h3 id="lcpインターバル" tabindex="-1"><a class="header-anchor" href="#lcpインターバル"><span>lcpインターバル</span></a></h3><p><img src="/RandomThoughts/assets/0003-xROzxSfh.png" alt="imgs/EnhancedSuffixArray/0003.png"></p><p><img src="/RandomThoughts/assets/0004-f9mW6UsF.png" alt="imgs/EnhancedSuffixArray/0004.png"></p><p>例</p><h3 id="mum" tabindex="-1"><a class="header-anchor" href="#mum"><span>MUM</span></a></h3><p><img src="/RandomThoughts/assets/0005-bSgQCOBk.png" alt="imgs/EnhancedSuffixArray/0005.png"></p><p><img src="/RandomThoughts/assets/0006-CY_uCbdz.png" alt="imgs/EnhancedSuffixArray/0006.png"></p><h2 id="lcpインターバルツリー" tabindex="-1"><a class="header-anchor" href="#lcpインターバルツリー"><span>lcpインターバルツリー</span></a></h2><p><img src="/RandomThoughts/assets/0007-BO1YqpXP.png" alt="imgs/EnhancedSuffixArray/0007.png"></p><h3 id="アルゴリズム4-1、インターバルのレポート" tabindex="-1"><a class="header-anchor" href="#アルゴリズム4-1、インターバルのレポート"><span>アルゴリズム4.1、インターバルのレポート</span></a></h3><p>より大きなlcpがでてくる都度スタックにpushしていき、より小さいlcpに出会ったらその一つ手前までをスタックトップのインターバルとして確定させていく。</p><p>Fig. 2に従いインターバルツリーを上から出力していこうと思うとこんなアルゴリズムになると思う。</p><h3 id="アルゴリズム4-4-ボトムアップトラバース" tabindex="-1"><a class="header-anchor" href="#アルゴリズム4-4-ボトムアップトラバース"><span>アルゴリズム4.4 ボトムアップトラバース</span></a></h3><p>lcpテーブルを順番に見ていってスタックを使うだけで、ツリーのトラバースをしたのと同じ結果が得られる。 インターバルが確定した時にはその子どものリストを持つ形の処理は全てこれで行える。</p><p><a href="./LempelZiv.html">LempelZiv</a>などを計算するのに使える。</p><h2 id="トップダウンとchildtab" tabindex="-1"><a class="header-anchor" href="#トップダウンとchildtab"><span>トップダウンとchildtab</span></a></h2><p><img src="/RandomThoughts/assets/0008-B8IEYzyq.png" alt="imgs/EnhancedSuffixArray/0008.png"></p><p><img src="/RandomThoughts/assets/0009-DPxGrMMp.png" alt="imgs/EnhancedSuffixArray/0009.png"></p><h3 id="childtabの構築" tabindex="-1"><a class="header-anchor" href="#childtabの構築"><span>childtabの構築</span></a></h3><p><img src="/RandomThoughts/assets/0010-CA3gpUUi.png" alt="imgs/EnhancedSuffixArray/0010.png"></p><p><img src="/RandomThoughts/assets/0011-D6aCgM0k.png" alt="imgs/EnhancedSuffixArray/0011.png"></p><h3 id="childtabを用いた子どものリストアップ" tabindex="-1"><a class="header-anchor" href="#childtabを用いた子どものリストアップ"><span>childtabを用いた子どものリストアップ</span></a></h3><p><img src="/RandomThoughts/assets/0012-u8mvbem0.png" alt="imgs/EnhancedSuffixArray/0012.png"></p><p><img src="/RandomThoughts/assets/0013-Caq3XbC3.png" alt="imgs/EnhancedSuffixArray/0013.png"></p><p><a href="./文字列マッチ.html">文字列マッチ</a>はprefix関数を使うが、こちらはより直接的に木を降りていく。</p><h2 id="esaxxの引数" tabindex="-1"><a class="header-anchor" href="#esaxxの引数"><span>esaxxの引数</span></a></h2><p><a href="./原論文から解き明かす生成AI.html">原論文から解き明かす生成AI</a>で出てくるSentence Pieceでは、以下が使われている。<a href="https://github.com/hillbig/esaxx" target="_blank" rel="noopener noreferrer">hillbig/esaxx: Automatically exported from code.google.com/p/esaxx</a></p><p>引数は<a href="https://github.com/hillbig/esaxx/blob/master/esa.hxx#L94C1-L110C4" target="_blank" rel="noopener noreferrer">esaxx/esa.hxx#L94-L110</a>に解説があるが、</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">/**</span>
<span class="line"> * @brief Build an enhanced suffix array of a given string in linear time</span>
<span class="line"> * For an input text T, esaxx() builds an enhancd suffix array in linear time. </span>
<span class="line"> * i-th internal node is represented as a triple (L[i], R[i], D[i]); </span>
<span class="line"> *   L[i] and R[i] is the left/right boundary of the suffix array as SA[L[i]....R[i]-1]</span>
<span class="line"> *   D[i] is the depth of the internal node</span>
<span class="line"> * The number of internal node is at most N-1 and return the actual number by </span>
<span class="line"> * @param T[0...n-1]  The input string. (random access iterator)</span>
<span class="line"> * @param SA[0...n-1] The output suffix array (random access iterator)</span>
<span class="line"> * @param L[0...n-1]  The output left boundary of internal node (random access iterator)</span>
<span class="line"> * @param R[0...n-1]  The output right boundary of internal node (random access iterator)</span>
<span class="line"> * @param D[0...n-1]  The output depth of internal node (random access iterator)</span>
<span class="line"> * @param n The length of the input string</span>
<span class="line"> * @param k The alphabet size</span>
<span class="line"> * @pram nodeNum The output the number of internal node</span>
<span class="line"> * @return 0 if succeded, -1 or -2 otherwise </span>
<span class="line"> */</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Depthとは何なのか、とか解説が無くて、 トリプレットはchildtabともちょっと違いそう。</p><p>出力結果やコードを眺めた印象だと、 lcpインターバルツリーの各ノードを表していそう。</p><p>i番目のノードがLiからRi-1までで、Diが共通prefixの長さになってそう。</p><p>ここからどうやって子ノードを探したりするのかは良く分からない。 Riは単調増加していて、同じRiに対してはLiは単調に減少しているので、 同じRiの狭いインターバルから広いインターバルに並んでいる。</p><p>たぶんツリー構造を復活させるルールがあるんだろうけれど、Sentence Pieceではそういう性質は使っていないので、知らなくてもSentence Pieceの理解には問題無い。上記の意味さえ理解しておけばコードは読めるし、これらがリニアタイムで構築出来るのも特に分からない事は無いだろう。</p><p>単に辿っていけばインターバルツリーのボトムアップトラバーサルにはなりそうで、親子関係は分かるはずなので、一回なめればトップダウン構造も再現できそうではある。</p><p>enumSubstring.cppをいじって配列を出してみた。 大したコードでは無いが将来再現したくなった時のために一応貼っておく。＞<a href="https://gist.github.com/karino2/e22da339a5eab350f450f1e6f6809ab0" target="_blank" rel="noopener noreferrer">gist: buildEsa.cpp</a></p><p>上記のノートのコドン配列だと以下。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ cat codon.txt</span>
<span class="line">acaaacatat</span>
<span class="line">$ ./buildEsa &lt; codon.txt</span>
<span class="line">    n:10</span>
<span class="line">alpha:256</span>
<span class="line"> Suffix Array:</span>
<span class="line">i	SA	L	R	D	substring:</span>
<span class="line">--------------------------------</span>
<span class="line">0	2	0	2	2	aaacatat</span>
<span class="line">1	3	2	4	3	aacatat</span>
<span class="line">2	0	4	6	2	acaaacatat</span>
<span class="line">3	4	0	6	1	acatat</span>
<span class="line">4	8	6	8	2	at</span>
<span class="line">5	6	8	10	1	atat</span>
<span class="line">6	1	0	10	0	caaacatat</span>
<span class="line">7	5	2	1	0	catat</span>
<span class="line">8	9	0	1	0	t</span>
<span class="line">9	7	1	0	0	tat</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>SAとsubstringは通常のsuffix arrayなのでいいだろう。</p><p>上記のSuffixツリーのノートと比べながら、上の行から順番に解釈していく。</p><p>1行目はLが0, Rが2なので、0から2-1、つまり0から1までが、プレフィクス2だけ共通、つまりこの場合は <code>lcptab[1] = 2</code> という事だろう。これはaaacatatとaacatatは先頭の2文字のaaだけ共通、という事。</p><p>2行目はLが2, Rが4でDが3なので、2から4-1、つまり2から3が、3文字共通、つまり<code>lcptab[3]=3</code>。acaaacatatとacatatは先頭のacaだけ共通、という事。</p><p>3行目も同様に4から5がatだけ共通</p><p>4行目は0から５がaだけ共通。</p><p>lcpインターバルツリーの下のインターバルから順番に書かれていて、その親は次に来る、という形式になっている。</p><p>2段階の子どもがaしか無いのがややこしくしているな。tの子どもも二段階にしてみよう。適当に末尾に足しただけなのでコドンとしては意味をなしてないが。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">% cat codon2.txt</span>
<span class="line">acaaacatatacta</span>
<span class="line">% ./buildEsa &lt; codon2.txt</span>
<span class="line">    n:14</span>
<span class="line">alpha:256</span>
<span class="line"> Suffix Array:</span>
<span class="line">i	SA	L	R	D	substring:</span>
<span class="line">--------------------------------</span>
<span class="line">0	13	1	3	2	a</span>
<span class="line">1	2	3	5	3	aaacatatacta</span>
<span class="line">2	3	3	6	2	aacatatacta</span>
<span class="line">3	0	6	8	3	acaaacatatacta</span>
<span class="line">4	4	0	8	1	acatatacta</span>
<span class="line">5	10	8	10	2	acta</span>
<span class="line">6	8	8	11	1	atacta</span>
<span class="line">7	6	11	14	2	atatacta</span>
<span class="line">8	1	0	14	0	caaacatatacta</span>
<span class="line">9	5	2	2	0	catatacta</span>
<span class="line">10	11	1	2	0	cta</span>
<span class="line">11	12	0	1	0	ta</span>
<span class="line">12	9	2	0	0	tacta</span>
<span class="line">13	7	2	0	0	tatacta</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>ツリーを描いてみると以下か？</p><p><img src="/RandomThoughts/assets/0014-CC1MFpCj.png" alt="imgs/EnhancedSuffixArray/0014.png"></p><p>注意する点</p><ul><li>最後の数字だけはSAの値で置き換えているのに注意 <ul><li>lcpインターバルツリーとして読むならiの値のままの方が分かりやすいのだが、Suffixツリーの定義では無くなってしまうので。</li></ul></li><li>lcpインターバルはRi-1なので1引いている</li><li>表を中間ノードだけを入れたテーブルとみなしてツリーの左下の（中間ノードの中で）一番子どもから順番に辿っていくと表と対応している <ul><li>1..2, 3..4, 3..5, 6..7, 0..7</li><li>子どもが揃ったら親に行く</li><li>兄弟に移る時はその一番子どもから始まる（Forestのtrailingだけ追うようなもの <a href="https://stlab.cc/2020/12/01/forest-introduction.html" target="_blank" rel="noopener noreferrer">Forest: An Introduction</a>）</li><li>Dはdepthと書いてあるがやはりlcp-intarvalのl値と解釈する方が正しそう（少なくともツリーの深さにはなっていない、taのノード参照）</li></ul></li></ul><p>やはりlcpインターバルツリーを再現しているデータ構造にはなっている。</p><p>トップダウントラバースは追加のデータ構造が必要そうだ。</p><p>LCPテーブル自体は返してないが（途中の計算で出しているのに…）、lcpインターバルツリーのl値は分かるのだから一回なめれば復元は出来る。</p>`,69)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};